package org.sleepwell.app;

import android.content.*;
import android.content.pm.*;
import android.net.Uri;
import android.os.*;
import android.provider.Settings;
import org.json.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;

/** Explicit private package grants, additional to Android URI enforcement. No portable authority. */
final class AlarmAccessGrants {
    private static final Object LOCK=new Object();private static final int MAX=8;private static volatile boolean blocked;
    private static SharedPreferences preferences(Context c){return c.getApplicationContext().getSharedPreferences("alarm_access_v1",Context.MODE_PRIVATE);}
    static final class Identity {
        final String name,pkg,signers;final int uid,boot;
        Identity(String name,String pkg,String signers,int uid,int boot){this.name=name;this.pkg=pkg;this.signers=signers;this.uid=uid;this.boot=boot;}
        boolean same(Identity other){return other!=null&&pkg.equals(other.pkg)&&uid==other.uid&&signers.equals(other.signers)&&boot==other.boot;}
    }
    static final class Grant {
        final Identity identity;final String nonce;final long time;final boolean active;
        Grant(Identity identity,String nonce,long time,boolean active){this.identity=identity;this.nonce=nonce;this.time=time;this.active=active;}
    }
    static final class Snapshot {final long revision;final List<Grant> grants;final String status;Snapshot(long revision,List<Grant> grants,String status){this.revision=revision;this.grants=List.copyOf(grants);this.status=status;}}
    static String operationStatus(Context c){return preferences(c).getString("operationStatus","");}
    static void operationStatus(Context c,String value){preferences(c).edit().putString("operationStatus",value.length()>240?value.substring(0,240):value).apply();}
    static final class Admission {final int uid,pid;final String pkg,nonce;final long revision,epoch;final boolean self;Admission(int uid,int pid,String pkg,String nonce,long revision,long epoch,boolean self){this.uid=uid;this.pid=pid;this.pkg=pkg;this.nonce=nonce;this.revision=revision;this.epoch=epoch;this.self=self;}}
    static int boot(Context c){try{int value=Settings.Global.getInt(c.getContentResolver(),Settings.Global.BOOT_COUNT,-1);if(value<0)throw new IllegalStateException();return value;}catch(RuntimeException unavailable){throw new IllegalStateException("Android boot identity is unavailable. Alarm access stays off.");}}
    @SuppressWarnings("deprecation") static Identity inspect(Context c,String pkg){
        if(pkg==null||pkg.length()>255||!pkg.matches("[A-Za-z][A-Za-z0-9_]*(\\.[A-Za-z][A-Za-z0-9_]*)+"))throw new IllegalArgumentException("Enter the installed app’s exact package name.");
        try{PackageManager pm=c.getPackageManager();PackageInfo info=pm.getPackageInfo(pkg,PackageManager.GET_SIGNING_CERTIFICATES);ApplicationInfo app=info.applicationInfo;if(app==null)throw new IllegalStateException("The app has no verifiable installed identity.");if(info.sharedUserId!=null&&!info.sharedUserId.isEmpty())throw new IllegalStateException("Shared-UID apps cannot be granted isolated alarm management.");String[] packages=pm.getPackagesForUid(app.uid);if(packages==null||packages.length!=1||!pkg.equals(packages[0]))throw new IllegalStateException("This UID cannot be isolated to one installed package.");if(app.uid<android.os.Process.FIRST_APPLICATION_UID||app.uid==android.os.Process.myUid())throw new IllegalStateException("Choose a separate installed app, not a system/shared identity or SleepWell itself.");SigningInfo signing=info.signingInfo;if(signing==null)throw new IllegalStateException("The installed app’s current signer is unavailable.");Signature[] current=signing.getApkContentsSigners();if(current==null||current.length<1||current.length>8)throw new IllegalStateException("The installed app’s current signers are unsupported.");SortedSet<String> hashes=new TreeSet<>();for(Signature signature:current)hashes.add(hex(MessageDigest.getInstance("SHA-256").digest(signature.toByteArray())));if(hashes.size()!=current.length)throw new IllegalStateException("Duplicate signer identity.");String name=pm.getApplicationLabel(app).toString().replaceAll("[\\p{Cntrl}\\p{Cf}]"," ").strip();if(name.length()>100)name=name.substring(0,100);return new Identity(name,pkg,String.join(",",hashes),app.uid,boot(c));
        }catch(PackageManager.NameNotFoundException absent){throw new IllegalArgumentException("This package is not installed or Android package visibility does not make it verifiable. Use a visible installed app.");}catch(NoSuchAlgorithmException unavailable){throw new IllegalStateException("Signer verification is unavailable.");}
    }
    private static String hex(byte[] bytes){StringBuilder text=new StringBuilder();for(byte value:bytes)text.append(String.format(Locale.ROOT,"%02x",value&255));return text.toString();}
    static Snapshot snapshot(Context c){synchronized(LOCK){SharedPreferences p=preferences(c);long revision=p.getLong("revision",0);String raw=p.getString("grants","[]");if(revision<0||raw==null||raw.length()>16384)throw new IllegalStateException("Alarm-access settings are unreadable. Use Revoke all.");try{JSONArray array=new JSONArray(raw);if(array.length()>MAX)throw new JSONException("Too many grants");List<Grant> grants=new ArrayList<>();Set<String> names=new HashSet<>();for(int n=0;n<array.length();n++){JSONObject row=array.getJSONObject(n);if(row.length()!=9)throw new JSONException("Unsupported grant fields");String pkg=row.getString("package"),signers=row.getString("signers"),nonce=row.getString("nonce"),name=row.getString("name");long uid=whole(row,"uid"),boot=whole(row,"boot"),time=whole(row,"time");Object active=row.get("active");if(whole(row,"version")!=1||uid<0||uid>Integer.MAX_VALUE||boot<0||boot>Integer.MAX_VALUE||time<0||pkg.length()>255||name.length()>100||!pkg.matches("[A-Za-z][A-Za-z0-9_]*(\\.[A-Za-z][A-Za-z0-9_]*)+")||!signers.matches("[0-9a-f]{64}(,[0-9a-f]{64}){0,7}")||!BackupRuntime.nonce(nonce)||!(active instanceof Boolean)||!names.add(pkg))throw new JSONException("Invalid grant");grants.add(new Grant(new Identity(name,pkg,signers,(int)uid,(int)boot),nonce,time,(Boolean)active));}return new Snapshot(revision,grants,p.getString("status","No apps are allowed."));}catch(JSONException|RuntimeException unreadable){throw new IllegalStateException("Alarm-access settings are unreadable. Use Revoke all.");}}}
    private static long whole(JSONObject row,String key)throws JSONException{return SoundEventBackup.whole(row,key);}
    private static String encode(List<Grant> grants){try{JSONArray rows=new JSONArray();for(Grant grant:grants)rows.put(new JSONObject().put("version",1).put("name",grant.identity.name).put("package",grant.identity.pkg).put("uid",grant.identity.uid).put("boot",grant.identity.boot).put("signers",grant.identity.signers).put("nonce",grant.nonce).put("time",grant.time).put("active",grant.active));return rows.toString();}catch(JSONException impossible){throw new IllegalStateException("Grant could not be encoded.");}}
    private static void persist(Context c,long expected,List<Grant> grants,String status){SharedPreferences p=preferences(c);long revision=p.getLong("revision",0);if(revision!=expected||revision>=Long.MAX_VALUE-2)throw new IllegalStateException("Alarm access changed. Reopen the review.");if(!p.edit().putString("grants",encode(grants)).putLong("revision",revision+1).putString("status",status).commit())throw new IllegalStateException("Alarm access could not be saved.");}
    static void allow(Context c,Identity reviewed,long expected){synchronized(LOCK){if(blocked)throw new IllegalStateException("Alarm access is blocked after an incomplete revoke. Revoke all first.");Snapshot before=snapshot(c);if(before.revision!=expected)throw new IllegalStateException("Alarm access changed. Verify the package again.");Identity current=inspect(c,reviewed.pkg);if(!reviewed.same(current))throw new IllegalStateException("The installed package, UID, signer or boot changed. Verify again.");List<Grant> prepared=new ArrayList<>(before.grants);prepared.removeIf(g->g.identity.pkg.equals(reviewed.pkg));if(prepared.size()>=MAX)throw new IllegalStateException("At most 8 apps can have alarm-access entries. Revoke one first.");String nonce=UUID.randomUUID().toString();Grant pending=new Grant(current,nonce,System.currentTimeMillis(),false);prepared.add(pending);persist(c,expected,prepared,"Preparing explicitly requested alarm-management access.");long epoch=SleepSummaryFiles.epoch();try{c.grantUriPermission(current.pkg,AlarmContentContract.ALARMS,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);if(!current.same(inspect(c,current.pkg))||epoch!=SleepSummaryFiles.epoch())throw new IllegalStateException("The app or history changed while allowing access.");List<Grant> allowed=new ArrayList<>(prepared);allowed.removeIf(g->g.identity.pkg.equals(current.pkg));allowed.add(new Grant(current,nonce,pending.time,true));persist(c,expected+1,allowed,"Alarm management allowed for "+current.pkg+" until revoke, reboot or identity change.");}catch(RuntimeException failure){try{c.revokeUriPermission(current.pkg,AlarmContentContract.ALARMS,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(RuntimeException ignored){blocked=true;}try{List<Grant> cleaned=new ArrayList<>(prepared);cleaned.removeIf(g->g.identity.pkg.equals(current.pkg));persist(c,preferences(c).getLong("revision",expected+1),cleaned,"Access was not completed. Verify and explicitly allow again.");}catch(RuntimeException ignored){blocked=true;}throw new IllegalStateException("Access was not completed; no active private grant was intentionally retained. Revoke all if the status needs attention.");}}}
    static void revoke(Context c,String pkg,long expected){synchronized(LOCK){Snapshot state=snapshot(c);if(state.revision!=expected)throw new IllegalStateException("Access changed. Refresh before revoking.");List<Grant> remaining=new ArrayList<>(state.grants);remaining.removeIf(g->g.identity.pkg.equals(pkg));persist(c,expected,remaining,"Access revoked for "+pkg+". Previously returned copies cannot be recalled.");try{c.revokeUriPermission(pkg,AlarmContentContract.ALARMS,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(RuntimeException unavailable){throw new IllegalStateException("Private access was revoked. Android URI cleanup was not confirmed; new API actions remain denied.");}}}
    /** Root calls only after incrementing the existing history epoch, before replacement/removal. */
    static void historyChanging(Context c){revokeAll(c,"History was replaced or erased. Alarm management grants were revoked; allow again explicitly.");}
    static void revokeAll(Context c,String status){synchronized(LOCK){blocked=true;SharedPreferences p=preferences(c);long revision;try{revision=p.getLong("revision",0);}catch(RuntimeException unreadable){revision=0;}if(revision<0||revision>=Long.MAX_VALUE-2)revision=0;if(!p.edit().clear().putLong("revision",revision+1).putString("grants","[]").putString("status",status).commit())throw new IllegalStateException("Private grants could not be cleared. History replacement must not continue.");try{c.revokeUriPermission(AlarmContentContract.ALARMS,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(RuntimeException unavailable){throw new IllegalStateException("New API actions are denied, but Android URI cleanup failed. Retry Revoke all.");}blocked=false;}}
    static String status(Context c,Grant grant){try{if(!grant.active)return "Not allowed · interrupted preparation";if(boot(c)!=grant.identity.boot)return "Expired after reboot · explicit Allow required";if(!grant.identity.same(inspect(c,grant.identity.pkg)))return "Package/UID/current signer changed · not allowed";if(c.checkUriPermission(AlarmContentContract.ALARMS,-1,grant.identity.uid,(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION))!=PackageManager.PERMISSION_GRANTED)return "Android read/write grant is absent · explicit Allow required";return blocked?"Blocked · Revoke all required":"Allowed · read + manage supported alarms";}catch(RuntimeException unavailable){return "Unavailable or changed · not allowed";}}
    static Admission admit(Context c,int uid,int pid,Uri uri,int mode){long epoch=SleepSummaryFiles.epoch();if(uid==android.os.Process.myUid())return new Admission(uid,pid,"","",-1,epoch,true);synchronized(LOCK){if(blocked)throw denied();Snapshot state;try{state=snapshot(c);}catch(RuntimeException invalid){throw denied();}String[] packages=c.getPackageManager().getPackagesForUid(uid);if(packages==null||packages.length!=1)throw denied();Grant selected=state.grants.stream().filter(g->g.active&&g.identity.uid==uid&&g.identity.pkg.equals(packages[0])).findFirst().orElse(null);if(selected==null)throw denied();try{if(!selected.identity.same(inspect(c,selected.identity.pkg))||c.checkUriPermission(uri,pid,uid,mode)!=PackageManager.PERMISSION_GRANTED)throw denied();}catch(RuntimeException invalid){throw denied();}return new Admission(uid,pid,selected.identity.pkg,selected.nonce,state.revision,epoch,false);}}
    static void current(Context c,Admission expected,Uri uri,int mode){if(SleepSummaryFiles.epoch()!=expected.epoch)throw denied();if(expected.self)return;Admission actual=admit(c,expected.uid,expected.pid,uri,mode);if(actual.revision!=expected.revision||!actual.pkg.equals(expected.pkg)||!actual.nonce.equals(expected.nonce)||actual.epoch!=expected.epoch)throw denied();}
    static void fastCurrent(Context c,Admission expected){if(SleepSummaryFiles.epoch()!=expected.epoch||blocked)throw denied();if(!expected.self&&preferences(c).getLong("revision",-1)!=expected.revision)throw denied();}
    static <T>T guarded(Context c,Admission caller,Uri uri,int mode,java.util.function.Supplier<T> operation){synchronized(LOCK){current(c,caller,uri,mode);return operation.get();}}
    private static SecurityException denied(){return new SecurityException("No current explicit SleepWell alarm-management grant for this caller.");}
    private AlarmAccessGrants(){}
}
